(function(){function o(){document.querySelectorAll(".ob-email").forEach(function(t){try{var e=atob(t.dataset.em);if(t.tagName==="A"){if(t.href="mailto:"+e,t.hasAttribute("data-label-behalten"))return;if(t.hasAttribute("data-nur-icon")){t.getAttribute("aria-label")||t.setAttribute("aria-label","E-Mail an "+e);return}t.childNodes.length>0?(t.childNodes.forEach(function(a){a.nodeType===3&&a.remove()}),t.appendChild(document.createTextNode(" "+e))):t.textContent=e}else t.textContent=e}catch{}}),document.querySelectorAll(".ob-tel").forEach(function(t){try{var e=atob(t.dataset.tel);if(t.tagName==="A"){if(t.href="tel:"+e.replace(/[\s\/]/g,""),t.hasAttribute("data-label-behalten"))return;t.childNodes.length>0?(t.childNodes.forEach(function(a){a.nodeType===3&&a.remove()}),t.appendChild(document.createTextNode(" "+e))):t.textContent=e}else t.textContent=e}catch{}})}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",o):o()})();
